<style>
:root{--xd4-green:#91bf3d;--xd4-ink:#222729;--xd4-muted:#697072;--xd4-container:min(1360px,calc(100% - 64px))}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;color:var(--xd4-ink);font-family:Arial,Helvetica,sans-serif;line-height:1.55}a{color:inherit;text-decoration:none}button,input{font:inherit}.xd4-container{width:var(--xd4-container);margin:auto}.xd4-header{position:absolute;z-index:20;top:0;left:0;width:100%;color:#fff}.xd4-header__inner{display:flex;min-height:108px;align-items:center;gap:28px}.xd4-brand{display:flex;flex:0 0 auto;align-items:center;gap:12px;font-size:30px;font-weight:700}.xd4-brand img{display:block;max-width:250px;max-height:78px;object-fit:contain}.xd4-brand__mark{display:grid;width:48px;height:48px;place-items:center;border:2px solid var(--xd4-green);border-radius:50%;color:var(--xd4-green);font-weight:900}.xd4-nav{display:flex;flex:1;justify-content:flex-end;gap:29px;font-size:15px;font-weight:700;text-transform:uppercase}.xd4-nav a{white-space:nowrap}.xd4-nav a:hover{color:var(--xd4-green)}.xd4-search{display:flex;align-items:center}.xd4-search input{display:none}.xd4-search button{border:0;background:transparent;color:#fff;font-size:29px;line-height:1;cursor:pointer}.xd4-quote{display:inline-flex;align-items:center;gap:17px;padding:15px 20px;background:var(--xd4-green);font-weight:700}.xd4-quote span{font-size:24px}.xd4-menu-toggle{display:none}.xd4-hero{position:relative;min-height:765px;overflow:hidden;background:#323638;color:#fff}.xd4-hero__slide{position:absolute;inset:0;opacity:0;transition:opacity .45s}.xd4-hero__slide.is-active{opacity:1}.xd4-hero__slide img{width:100%;height:100%;object-fit:cover}.xd4-hero__veil{position:absolute;inset:0;background:rgba(26,30,33,.53)}.xd4-hero__content{position:relative;z-index:2;display:flex;min-height:690px;align-items:center;justify-content:flex-end;padding:150px 9% 90px}.xd4-hero__copy{width:min(680px,52%);text-align:right}.xd4-eyebrow{margin:0 0 16px;color:var(--xd4-green);font-size:18px;font-weight:700}.xd4-hero h1,.xd4-section-title{margin:0;font-size:clamp(37px,4vw,58px);font-weight:800;line-height:1.13;text-transform:uppercase}.xd4-hero p{margin:24px 0 0;font-size:18px}.xd4-actions{display:flex;justify-content:flex-end;gap:12px;margin-top:34px}.xd4-button{display:inline-flex;align-items:center;justify-content:center;min-height:54px;padding:0 26px;background:var(--xd4-green);color:#fff;font-weight:700}.xd4-button--outline{border:2px solid #fff;background:transparent}.xd4-hero__arrow{position:absolute;z-index:3;top:48%;display:grid;width:62px;height:62px;place-items:center;border:1px solid #fff;border-radius:50%;background:transparent;color:#fff;font-size:42px;cursor:pointer}.xd4-hero__arrow--prev{left:28px}.xd4-hero__arrow--next{right:28px}.xd4-categories{position:relative;z-index:5;margin-top:-72px;padding:72px 0 42px;background:var(--xd4-green)}.xd4-category-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:22px}.xd4-category{min-height:280px;padding:31px 27px;background:#fff}.xd4-category__icon{display:grid;width:64px;height:64px;place-items:center;margin-bottom:18px;background:var(--xd4-green);color:#fff;font-size:26px;font-weight:700;transform:rotate(45deg)}.xd4-category__icon span{transform:rotate(-45deg)}.xd4-category h3{margin:0 0 13px;font-size:24px;line-height:1.2;text-transform:uppercase}.xd4-category p{margin:0;color:var(--xd4-muted)}.xd4-section{padding:100px 0;background:#fff}.xd4-section-head{text-align:center}.xd4-section-head p{margin:0 0 8px;color:var(--xd4-green);font-size:18px;font-weight:700}.xd4-section-head .xd4-section-title{font-size:43px}.xd4-solutions{display:grid;grid-template-columns:1fr 1fr;gap:38px 72px;margin-top:52px}.xd4-solution{display:grid;grid-template-columns:minmax(190px,44%) 1fr;gap:32px;align-items:center}.xd4-solution img{width:100%;height:300px;object-fit:cover}.xd4-solution h3{margin:0 0 16px;font-size:27px;line-height:1.2}.xd4-solution p{margin:0;color:var(--xd4-muted);font-size:17px}.xd4-read-more{display:inline-flex;margin-top:22px;color:var(--xd4-green);font-weight:700}.xd4-feature{display:grid;grid-template-columns:46% 54%;width:min(1260px,100%);margin:0 auto}.xd4-feature__image{min-height:630px;background:#667}.xd4-feature__image img{width:100%;height:100%;object-fit:cover}.xd4-feature__body{padding:80px 9%;background:var(--xd4-ink);color:#fff}.xd4-feature__body .xd4-eyebrow{font-size:18px}.xd4-feature__body h2{margin:0;font-size:clamp(34px,3.3vw,51px);line-height:1.2;text-transform:uppercase}.xd4-feature__body>p{color:#e4e6e5;font-size:18px}.xd4-feature-points{display:grid;grid-template-columns:1fr 1fr;gap:30px;margin:36px 0}.xd4-feature-points h3{margin:0 0 9px;font-size:21px}.xd4-feature-points p{margin:0;color:#e4e6e5}.xd4-stat{padding-top:23px;border-top:1px solid #ffffff33;font-weight:700}.xd4-gallery-head{display:grid;grid-template-columns:1.05fr 1fr auto;align-items:center;gap:45px;margin-bottom:42px}.xd4-gallery-head p{margin:0;color:var(--xd4-muted);font-size:17px}.xd4-gallery{display:grid;grid-template-columns:repeat(4,1fr);gap:24px}.xd4-gallery-card img{display:block;width:100%;height:245px;object-fit:cover}.xd4-gallery-card h3{margin:16px 0 0;font-size:20px;text-align:center;text-transform:uppercase}.xd4-partners{padding:70px 0;background:var(--xd4-green)}.xd4-partner-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:14px}.xd4-partner{display:grid;min-height:132px;place-items:center;padding:18px;border:1px solid #ffffff1f;background:#ffffff0a;text-align:center}.xd4-partner img{max-width:180px;max-height:76px;object-fit:contain;filter:brightness(0) invert(1)}.xd4-partner strong{color:#fff;font-size:18px}.xd4-footer{padding:74px 0 0;background:#222729;color:#fff}.xd4-footer__grid{display:grid;grid-template-columns:1.2fr 1fr 1fr 1.2fr;gap:38px;padding-bottom:54px}.xd4-footer .xd4-brand{margin-bottom:24px}.xd4-footer p,.xd4-footer li{color:#c9cdcd}.xd4-footer h3{margin:5px 0 22px;font-size:21px;text-transform:uppercase}.xd4-footer ul{display:grid;gap:11px;margin:0;padding:0;list-style:none}.xd4-footer li:before{margin-right:9px;color:var(--xd4-green);content:"â€º";font-size:18px}.xd4-newsletter{display:grid;grid-template-columns:1fr 58px;margin-top:20px}.xd4-newsletter input{min-width:0;height:54px;border:0;padding:0 16px}.xd4-newsletter button{border:0;background:var(--xd4-green);color:#fff;font-size:26px;cursor:pointer}.xd4-footer__bottom{padding:18px;border-top:1px solid #ffffff18;color:#a7aaaa;font-size:13px;text-align:center}@media(max-width:1050px){.xd4-header{position:relative;background:var(--xd4-ink)}.xd4-header__inner{min-height:82px}.xd4-nav{gap:16px;font-size:13px}.xd4-hero{min-height:650px}.xd4-category-grid,.xd4-gallery{grid-template-columns:repeat(2,1fr)}.xd4-partner-grid{grid-template-columns:repeat(3,1fr)}.xd4-footer__grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:720px){:root{--xd4-container:min(100% - 30px,1360px)}.xd4-header__inner{flex-wrap:wrap;gap:15px;padding:14px 0}.xd4-brand{font-size:21px}.xd4-brand img{max-width:180px;max-height:60px}.xd4-menu-toggle{display:block;margin-left:auto;border:1px solid #ffffff66;background:transparent;color:#fff;padding:8px 13px}.xd4-nav{display:none;flex-basis:100%;order:3;flex-direction:column;align-items:flex-start;padding-top:10px}.xd4-nav.is-open{display:flex}.xd4-search,.xd4-quote{display:none}.xd4-hero{min-height:570px}.xd4-hero__content{min-height:570px;align-items:flex-end;padding:80px 15px 55px}.xd4-hero__copy{width:100%;text-align:left}.xd4-hero h1{font-size:37px}.xd4-hero p{font-size:16px}.xd4-actions{justify-content:flex-start}.xd4-hero__arrow{display:none}.xd4-categories{margin-top:0;padding:35px 0;background:var(--xd4-green)}.xd4-category-grid,.xd4-solutions,.xd4-gallery,.xd4-feature-points,.xd4-footer__grid{grid-template-columns:1fr}.xd4-category{min-height:0}.xd4-section{padding:65px 0}.xd4-section-head .xd4-section-title{font-size:31px}.xd4-solution{grid-template-columns:1fr;gap:18px}.xd4-solution img{height:230px}.xd4-feature{grid-template-columns:1fr}.xd4-feature__image{min-height:300px}.xd4-feature__body{padding:50px 30px}.xd4-gallery-head{display:block}.xd4-gallery-head p{margin:18px 0}.xd4-gallery-card img{height:220px}.xd4-partner-grid{grid-template-columns:repeat(2,1fr)}}
</style>
